#include "helpers/PlaneHelper.h"
namespace{std::shared_ptr<BufferGeometry> createGeometry(){auto result=Helper_detail::geometry({1,-1,0,-1,1,0,-1,-1,0,1,1,0,-1,1,0,-1,-1,0,1,-1,0,1,1,0});result->computeBoundingSphere();return result;}}
PlaneHelper::PlaneHelper(std::shared_ptr<Plane> value,double size,HelperColor color):Line(createGeometry(),Helper_detail::lineMaterial(color.value)),plane(std::move(value)),size(size){type="PlaneHelper";auto geometry2=Helper_detail::geometry({1,1,0,-1,1,0,-1,-1,0,1,1,0,-1,-1,0,1,-1,0});geometry2->computeBoundingSphere();auto material2=Helper_detail::meshMaterial(color.value);material2->opacity=.2;material2->transparent=true;material2->depthWrite=false;add(std::make_shared<Mesh>(geometry2,material2));}
void PlaneHelper::updateMatrixWorld(bool force){position.set(0,0,0);scale.set(.5*size,.5*size,1);if(!plane)throw JSTypeError("Cannot read properties of undefined (reading 'normal')");lookAt(plane->normal);translateZ(-plane->constant);Line::updateMatrixWorld(force);}
std::shared_ptr<Object3D> PlaneHelper::clone(bool recursive)const{auto result=std::make_shared<PlaneHelper>();result->copy(*this,recursive);return result;}
void PlaneHelper::dispose(){Line::dispose();Helper_detail::disposeGeometry(geometry);Helper_detail::disposeMaterial(material);Helper_detail::disposeGeometry(Helper_detail::childMesh(*this)->geometry);Helper_detail::disposeMaterial(Helper_detail::childMesh(*this)->material);}
